246],[37.731781,-2.969174],[37.73198,-2.969105],[37.732038,-2.969096],[37.732106,-2.969081],[37.732168,-2.969095],[37.732176,-2.969128],[37.732194,-2.969114],[37.732142,-2.968969],[37.732037,-2.968773],[37.732111,-2.968599],[37.732106,-2.968581],[37.7321,-2.968599],[37.732137,-2.968607],[37.732207,-2.968669],[37.732243,-2.968694],[37.732284,-2.968724],[37.732298,-2.968806],[37.732301,-2.968834],[37.732268,-2.96887],[37.73232,-2.968907],[37.732322,-2.968927],[37.732314,-2.968908],[37.732442,-2.969043],[37.732523,-2.969062],[37.732747,-2.969109],[37.733068,-2.969158],[37.733126,-2.96919],[37.733237,-2.969212],[37.733339,-2.969222],[37.733388,-2.969213],[37.733427,-2.96921],[37.733482,-2.969234],[37.733604,-2.969268],[37.733759,-2.969258],[37.733784,-2.969257],[37.733787,-2.969161],[37.733835,-2.969242],[37.733986,-2.969238],[37.734054,-2.969304],[37.734106,-2.96917],[37.734151,-2.969249],[37.734397,-2.969532],[37.734387,-2.969627],[37.734387,-2.969624],[37.734386,-2.969607],[37.734429,-2.969533],[37.734466,-2.969249],[37.734532,-2.969056],[37.734523,-2.969055],[37.734581,-2.969048],[37.734573,-2.969043],[37.734888,-2.969189],[37.735078,-2.969419],[37.735259,-2.969639],[37.735354,-2.969772],[37.735593,-2.970138],[37.735592,-2.970139],[37.735612,-2.970179],[37.73565,-2.97022],[37.735619,-2.970184],[37.735616,-2.970173],[37.735639,-2.970193],[37.735689,-2.970309],[37.735682,-2.970296],[37.73577,-2.970394],[37.736474,-2.970369],[37.73681,-2.970282],[37.736813,-2.97028]]}]'::jsonb;
  v_source jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_loop_gap_km double precision;
  v_invalid integer;
begin
  for v_source in select value from jsonb_array_elements(v_sources) as x(value) loop
    select h.id,h.latitude,h.longitude,h.distance_km,t.status
      into v_route
      from public.hiking_routes h
      join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_source->>'route_id'
        and h.source='openstreetmap'
        and h.name=v_source->>'expected_name'
        and h.official_url=v_source->>'old_url'
        and exists (select 1 from public.hiking_route_regions r
          where r.route_id=h.id and r.published);
    if not found then
      raise exception 'FADMES route identity or published region changed: %',
        v_source->>'route_id';
    end if;
    if v_route.status='ready' then continue; end if;
    if v_route.status<>'missing' then
      raise exception 'FADMES route status changed: %',v_source->>'route_id';
    end if;
    with points as (
      select ordinality idx,(point->>0)::double precision lat,
        (point->>1)::double precision lon
      from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point,ordinality)
    ), steps as (
      select *,lag(lat) over(order by idx) prev_lat,
        lag(lon) over(order by idx) prev_lon from points
    ), distances as (
      select case when prev_lat is null then 0 else
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
        (lat between 27 and 45 and lon between -19 and 5) valid from steps
    ) select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
        coalesce(min(center_km),999),count(*) filter(where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;
    select ST_DistanceSphere(
        ST_MakePoint((v_source->'coords'->0->>1)::double precision,
          (v_source->'coords'->0->>0)::double precision),
        ST_MakePoint((v_source->'coords'->(v_count-1)->>1)::double precision,
          (v_source->'coords'->(v_count-1)->>0)::double precision))/1000
      into v_loop_gap_km;
    if v_count<>(v_source->>'expected_points')::integer or v_count<50
      or v_invalid>0 or v_length_km<=0 or v_max_gap_km>0.15
      or v_center_gap_km>0.60
      or ((v_source->>'circular')::boolean and v_loop_gap_km>0.10)
      or abs(v_length_km/(v_source->>'official_km')::double precision-1)>0.12
      or (v_route.distance_km is not null
        and abs(v_length_km/v_route.distance_km-1)>0.12) then
      raise exception 'FADMES track validation failed for %: points %, length %, gap %, center %, loop %, invalid %',
        v_source->>'route_id',v_count,v_length_km,v_max_gap_km,
        v_center_gap_km,v_loop_gap_km,v_invalid;
    end if;
    select jsonb_agg(jsonb_build_object('lat',(point->>0)::double precision,
      'lon',(point->>1)::double precision) order by ordinality)
      into v_points from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point,ordinality);
    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (v_source->>'route_id','ready',jsonb_build_array(v_points),
      now(),true,'FADMES - Directorio de senderos homologados',
      v_source->>'gpx_url',true)
    on conflict(route_id) do update set
      status=excluded.status,segments=excluded.segments,
      checked_at=excluded.checked_at,continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,official=true;
    update public.hiking_routes
      set trace_available=true,published=true,
        official_url=v_source->>'page_url'
      where id=v_source->>'route_id';
  end loop;
end
